$field=function($f){
  [$k,$label,$type,$opt,$help,$show]=$f+[2=>'text',3=>null,4=>'',5=>''];
  $v=setting($k);
  $o='<label class="'.($type==='textarea'?'full':'').'"'.($show?' data-show="'.e($show).'"':'').'>'.e($label);
  if($type==='textarea')$o.='<textarea name="'.$k.'" rows="'.(in_array($k,['services','company_address','company_about','voice_task'],true)?4:3).'" class="'.(strpos($k,'_api_')!==false||strpos($k,'voice_')===0&&$k!=='voice_task'?'mono':'').'">'.e($v).'</textarea>';
  elseif($type==='select'){$o.='<select name="'.$k.'"'.(in_array($k,['wa_provider','voice_provider','mail_transport','smtp_provider','mail_api','imap_on'],true)?' data-toggle':'').'>';foreach($opt as $ov=>$ol)$o.='<option value="'.e($ov).'" '.((string)$v===(string)$ov?'selected':'').'>'.e($ol).'</option>';$o.='</select>';}
  elseif($type==='secret')$o.='<input type="password" name="'.$k.'" autocomplete="new-password" placeholder="'.($v!==''?'•••••••• saved – type to replace':'Not set').'">'.($v!==''?'<span class="chk sm" style="margin-top:6px"><input type="checkbox" name="clear_'.$k.'" value="1"> remove saved value</span>':'');
  elseif($type==='days'){$on=explode(',',$v);$o.='<span class="row" style="margin-top:8px">';foreach(['1'=>'Mon','2'=>'Tue','3'=>'Wed','4'=>'Thu','5'=>'Fri','6'=>'Sat','7'=>'Sun'] as $d=>$dn)$o.='<span class="chk"><input type="checkbox" name="'.$k.'[]" value="'.$d.'" '.(in_array($d,$on,true)?'checked':'').'>'.$dn.'</span>';$o.='</span>';}
  elseif($type==='file'){$o.='<input type="file" name="'.$k.'" accept="'.e($opt).'">';if($v&&strpos($k,'company_logo')===0)$o.='<span class="logo-pv" style="background:'.($k==='company_logo'?e(setting('brand_primary','#0B0B0B')):'#fff;border:1px solid #E5E7EB').'"><img src="'.e($v).'" alt=""></span>'.($k==='company_logo_light'?'<span class="chk sm" style="margin-top:6px"><input type="checkbox" name="remove_logo_light" value="1"> remove</span>':'');elseif($v&&$k==='proposal_pdf')$o.='<span class="sm" style="display:block;margin-top:6px">Current: <b>'.e(basename($v)).'</b> <span class="chk sm"><input type="checkbox" name="remove_proposal" value="1"> remove</span></span>';}
  elseif($type==='color')$o.='<span class="clr"><input type="color" value="'.e($v).'" oninput="this.nextElementSibling.value=this.value"><input name="'.$k.'" value="'.e($v).'" oninput="this.previousElementSibling.value=this.value"></span>';
  else $o.='<input type="'.($type==='number'?'number':'text').'" name="'.$k.'" value="'.e($v).'">';
  if($help)$o.='<small>'.e($help).'</small>';
  return $o.'</label>';};
